@Test
public void testPartitionAwareSegmentPruner() {
    BrokerRequest brokerRequest1 = CalciteSqlCompiler.compileToBrokerRequest(QUERY_1);
    BrokerRequest brokerRequest2 = CalciteSqlCompiler.compileToBrokerRequest(QUERY_2);
    BrokerRequest brokerRequest3 = CalciteSqlCompiler.compileToBrokerRequest(QUERY_3);
    BrokerRequest brokerRequest4 = CalciteSqlCompiler.compileToBrokerRequest(QUERY_4);
    // NOTE: Ideal state and external view are not used in the current implementation
    IdealState idealState = Mockito.mock(IdealState.class);
    ExternalView externalView = Mockito.mock(ExternalView.class);
    SinglePartitionColumnSegmentPruner singlePartitionColumnSegmentPruner = new SinglePartitionColumnSegmentPruner(OFFLINE_TABLE_NAME, PARTITION_COLUMN_1, _propertyStore);
    Set<String> onlineSegments = new HashSet<>();
    singlePartitionColumnSegmentPruner.init(idealState, externalView, onlineSegments);
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest1, Collections.emptySet()), Collections.emptySet());
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest2, Collections.emptySet()), Collections.emptySet());
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest3, Collections.emptySet()), Collections.emptySet());
    // Segments without metadata (not updated yet) should not be pruned
    String newSegment = "newSegment";
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest1, Collections.singleton(newSegment)), Collections.singletonList(newSegment));
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest2, Collections.singleton(newSegment)), Collections.singletonList(newSegment));
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest3, Collections.singleton(newSegment)), Collections.singletonList(newSegment));
    // Segments without partition metadata should not be pruned
    String segmentWithoutPartitionMetadata = "segmentWithoutPartitionMetadata";
    onlineSegments.add(segmentWithoutPartitionMetadata);
    SegmentZKMetadata segmentZKMetadataWithoutPartitionMetadata = new SegmentZKMetadata(segmentWithoutPartitionMetadata);
    ZKMetadataProvider.setSegmentZKMetadata(_propertyStore, OFFLINE_TABLE_NAME, segmentZKMetadataWithoutPartitionMetadata);
    singlePartitionColumnSegmentPruner.onAssignmentChange(idealState, externalView, onlineSegments);
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest1, new HashSet<>(Collections.singletonList(segmentWithoutPartitionMetadata))), Collections.singletonList(segmentWithoutPartitionMetadata));
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest2, new HashSet<>(Collections.singletonList(segmentWithoutPartitionMetadata))), Collections.singletonList(segmentWithoutPartitionMetadata));
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest3, new HashSet<>(Collections.singletonList(segmentWithoutPartitionMetadata))), Collections.singletonList(segmentWithoutPartitionMetadata));
    // Test different partition functions and number of partitions
    // 0 % 5 = 0; 1 % 5 = 1; 2 % 5 = 2
    String segment0 = "segment0";
    onlineSegments.add(segment0);
    setSegmentZKPartitionMetadata(OFFLINE_TABLE_NAME, segment0, "Modulo", 5, 0);
    // Murmur(0) % 4 = 0; Murmur(1) % 4 = 3; Murmur(2) % 4 = 0
    String segment1 = "segment1";
    onlineSegments.add(segment1);
    setSegmentZKPartitionMetadata(OFFLINE_TABLE_NAME, segment1, "Murmur", 4, 0);
    singlePartitionColumnSegmentPruner.onAssignmentChange(idealState, externalView, onlineSegments);
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest1, new HashSet<>(Arrays.asList(segment0, segment1))), new HashSet<>(Arrays.asList(segment0, segment1)));
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest2, new HashSet<>(Arrays.asList(segment0, segment1))), new HashSet<>(Arrays.asList(segment0, segment1)));
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest3, new HashSet<>(Arrays.asList(segment0, segment1))), new HashSet<>(Collections.singletonList(segment1)));
    // Update partition metadata without refreshing should have no effect
    setSegmentZKPartitionMetadata(OFFLINE_TABLE_NAME, segment0, "Modulo", 4, 1);
    singlePartitionColumnSegmentPruner.onAssignmentChange(idealState, externalView, onlineSegments);
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest1, new HashSet<>(Arrays.asList(segment0, segment1))), new HashSet<>(Arrays.asList(segment0, segment1)));
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest2, new HashSet<>(Arrays.asList(segment0, segment1))), new HashSet<>(Arrays.asList(segment0, segment1)));
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest3, new HashSet<>(Arrays.asList(segment0, segment1))), new HashSet<>(Collections.singletonList(segment1)));
    // Refresh the changed segment should update the segment pruner
    singlePartitionColumnSegmentPruner.refreshSegment(segment0);
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest1, new HashSet<>(Arrays.asList(segment0, segment1))), new HashSet<>(Arrays.asList(segment0, segment1)));
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest2, new HashSet<>(Arrays.asList(segment0, segment1))), new HashSet<>(Collections.singletonList(segment1)));
    assertEquals(singlePartitionColumnSegmentPruner.prune(brokerRequest3, new HashSet<>(Arrays.asList(segment0, segment1))), new HashSet<>(Arrays.asList(segment0, segment1)));
    // Multi-column partitioned segment.
    MultiPartitionColumnsSegmentPruner multiPartitionColumnsSegmentPruner = new MultiPartitionColumnsSegmentPruner(OFFLINE_TABLE_NAME, Stream.of(PARTITION_COLUMN_1, PARTITION_COLUMN_2).collect(Collectors.toSet()), _propertyStore);
    multiPartitionColumnsSegmentPruner.init(idealState, externalView, onlineSegments);
    assertEquals(multiPartitionColumnsSegmentPruner.prune(brokerRequest1, Collections.emptySet()), Collections.emptySet());
    assertEquals(multiPartitionColumnsSegmentPruner.prune(brokerRequest2, Collections.emptySet()), Collections.emptySet());
    assertEquals(multiPartitionColumnsSegmentPruner.prune(brokerRequest3, Collections.emptySet()), Collections.emptySet());
    assertEquals(multiPartitionColumnsSegmentPruner.prune(brokerRequest4, Collections.emptySet()), Collections.emptySet());
    String segment2 = "segment2";
    onlineSegments.add(segment2);
    Map<String, ColumnPartitionMetadata> columnPartitionMetadataMap = new HashMap<>();
    columnPartitionMetadataMap.put(PARTITION_COLUMN_1, new ColumnPartitionMetadata("Modulo", 4, Collections.singleton(0), null));
    Map<String, String> partitionColumn2FunctionConfig = new HashMap<>();
    partitionColumn2FunctionConfig.put("columnValues", "xyz|abc");
    partitionColumn2FunctionConfig.put("columnValuesDelimiter", "|");
    columnPartitionMetadataMap.put(PARTITION_COLUMN_2, new ColumnPartitionMetadata("BoundedColumnValue", 3, Collections.singleton(1), partitionColumn2FunctionConfig));
    setSegmentZKPartitionMetadata(OFFLINE_TABLE_NAME, segment2, columnPartitionMetadataMap);
    multiPartitionColumnsSegmentPruner.onAssignmentChange(idealState, externalView, onlineSegments);
    assertEquals(multiPartitionColumnsSegmentPruner.prune(brokerRequest1, new HashSet<>(Arrays.asList(segment0, segment1))), new HashSet<>(Arrays.asList(segment0, segment1)));
    assertEquals(multiPartitionColumnsSegmentPruner.prune(brokerRequest2, new HashSet<>(Arrays.asList(segment0, segment1))), new HashSet<>(Collections.singletonList(segment1)));
    assertEquals(multiPartitionColumnsSegmentPruner.prune(brokerRequest3, new HashSet<>(Arrays.asList(segment0, segment1))), new HashSet<>(Arrays.asList(segment0, segment1)));
    assertEquals(multiPartitionColumnsSegmentPruner.prune(brokerRequest4, new HashSet<>(Arrays.asList(segment0, segment1, segment2))), new HashSet<>(Arrays.asList(segment1, segment2)));
}

