@Test
public void testListFilesWithMetadataNonRecursive() throws IOException {
    ADLStoreClient adlStoreClient = Mockito.mock(ADLStoreClient.class);
    AzurePinotFS azurePinotFS = new AzurePinotFS(adlStoreClient);
    URI baseURI = new File(_adlLocation, "testDirNonRecursive").toURI();
    Date lastModifiedTime = new Date();
    Date lastAccessTime = new Date();
    DirectoryEntry testDir = new DirectoryEntry("testDir", baseURI.toString(), 1024, null, null, lastAccessTime, lastModifiedTime, DirectoryEntryType.DIRECTORY, 128, 1, null, false, null);
    Mockito.when(adlStoreClient.getDirectoryEntry(baseURI.getPath())).thenReturn(testDir);
    List<DirectoryEntry> entries = new ArrayList<>();
    DirectoryEntry dir = new DirectoryEntry("dir1", testDir.fullName + "/dir1", 128, null, null, lastAccessTime, lastModifiedTime, DirectoryEntryType.DIRECTORY, 128, 1, null, false, null);
    entries.add(dir);
    DirectoryEntry file = new DirectoryEntry("file1", testDir.fullName + "/file1", 1024, null, null, lastAccessTime, lastModifiedTime, DirectoryEntryType.FILE, 128, 1, null, false, null);
    entries.add(file);
    Mockito.when(adlStoreClient.enumerateDirectory(Mockito.anyString())).thenReturn(entries);
    String[] files = azurePinotFS.listFiles(baseURI, false);
    Assert.assertEquals(files.length, 2);
    Assert.assertTrue(entries.stream().map(d -> d.fullName).collect(Collectors.toSet()).containsAll(Arrays.asList(files)), Arrays.toString(files));
    List<FileMetadata> fileMetadata = azurePinotFS.listFilesWithMetadata(baseURI, false);
    Assert.assertEquals(fileMetadata.size(), 2);
    Assert.assertTrue(entries.stream().map(d -> d.fullName).collect(Collectors.toSet()).containsAll(fileMetadata.stream().map(FileMetadata::getFilePath).collect(Collectors.toSet())), fileMetadata.toString());
    Assert.assertEquals(fileMetadata.stream().filter(FileMetadata::isDirectory).count(), 1);
    Assert.assertEquals(fileMetadata.stream().filter(f -> !f.isDirectory()).count(), 1);
}

