    Mockito.when(_rightOperator.nextBlock()).thenReturn(OperatorTestUtil.block(rightSchema, new Object[] { 2, "Aa" }, new Object[] { 2, "BB" }, new Object[] { 3, "BB" })).thenReturn(TransferableBlockUtils.getEndOfStreamTransferableBlock());
