@Test
public void shouldHandleNoOpBlock() {
    DataSchema leftSchema = new DataSchema(new String[] { "int_col", "string_col" }, new DataSchema.ColumnDataType[] { DataSchema.ColumnDataType.INT, DataSchema.ColumnDataType.STRING });
    DataSchema rightSchema = new DataSchema(new String[] { "int_col", "string_col" }, new DataSchema.ColumnDataType[] { DataSchema.ColumnDataType.INT, DataSchema.ColumnDataType.STRING });
    Mockito.when(_leftOperator.nextBlock()).thenReturn(OperatorTestUtil.block(leftSchema, new Object[] { 2, "BB" })).thenReturn(TransferableBlockUtils.getNoOpTransferableBlock()).thenReturn(OperatorTestUtil.block(leftSchema, new Object[] { 2, "CC" })).thenReturn(TransferableBlockUtils.getEndOfStreamTransferableBlock());
    Mockito.when(_rightOperator.nextBlock()).thenReturn(OperatorTestUtil.block(rightSchema, new Object[] { 1, "BB" })).thenReturn(TransferableBlockUtils.getNoOpTransferableBlock()).thenReturn(OperatorTestUtil.block(rightSchema, new Object[] { 2, "Aa" })).thenReturn(TransferableBlockUtils.getNoOpTransferableBlock()).thenReturn(TransferableBlockUtils.getEndOfStreamTransferableBlock());
    List<RexExpression> joinClauses = new ArrayList<>();
    DataSchema resultSchema = new DataSchema(new String[] { "int_col1", "string_col1", "int_co2", "string_col2" }, new DataSchema.ColumnDataType[] { DataSchema.ColumnDataType.INT, DataSchema.ColumnDataType.STRING, DataSchema.ColumnDataType.INT, DataSchema.ColumnDataType.STRING });
    JoinNode node = new JoinNode(1, resultSchema, JoinRelType.INNER, getJoinKeys(Arrays.asList(0), Arrays.asList(0)), joinClauses);
    HashJoinOperator join = new HashJoinOperator(_leftOperator, _rightOperator, leftSchema, node, 1, 2);
    // first no-op consumes first right data block.
    TransferableBlock result = join.nextBlock();
    Assert.assertTrue(result.isNoOpBlock());
    // second no-op consumes no-op right block.
    result = join.nextBlock();
    Assert.assertTrue(result.isNoOpBlock());
    // third no-op consumes two right data blocks and builds result
    result = join.nextBlock();
    List<Object[]> resultRows = result.getContainer();
    List<Object[]> expectedRows = ImmutableList.of(new Object[] { 2, "BB", 2, "Aa" });
    Assert.assertEquals(resultRows.size(), expectedRows.size());
    Assert.assertEquals(resultRows.get(0), expectedRows.get(0));
    // second left block is no-op
    result = join.nextBlock();
    Assert.assertTrue(result.isNoOpBlock());
    // third left block consumes some extra data
    result = join.nextBlock();
    expectedRows = ImmutableList.of(new Object[] { 2, "CC", 2, "Aa" });
    resultRows = result.getContainer();
    Assert.assertEquals(resultRows.size(), expectedRows.size());
    Assert.assertEquals(resultRows.get(0), expectedRows.get(0));
    // last one is EOS.
    result = join.nextBlock();
    Assert.assertTrue(result.isEndOfStreamBlock());
}

