@Test
public void testNoopBlock() {
    DataSchema upStreamSchema = new DataSchema(new String[] { "string1", "string2" }, new DataSchema.ColumnDataType[] { DataSchema.ColumnDataType.STRING, DataSchema.ColumnDataType.STRING });
    Mockito.when(_upstreamOp.nextBlock()).thenReturn(OperatorTestUtil.block(upStreamSchema, new Object[] { "a", "a" }, new Object[] { "b", "b" })).thenReturn(TransferableBlockUtils.getNoOpTransferableBlock()).thenReturn(OperatorTestUtil.block(upStreamSchema, new Object[] { "c", "c" }, new Object[] { "d", "d" }, new Object[] { "e", "e" }));
    RexExpression.Literal boolLiteral = new RexExpression.Literal(FieldSpec.DataType.BOOLEAN, true);
    RexExpression.Literal strLiteral = new RexExpression.Literal(FieldSpec.DataType.STRING, "str");
    DataSchema resultSchema = new DataSchema(new String[] { "boolCol", "strCol" }, new DataSchema.ColumnDataType[] { DataSchema.ColumnDataType.BOOLEAN, DataSchema.ColumnDataType.STRING });
    TransformOperator op = new TransformOperator(_upstreamOp, resultSchema, ImmutableList.of(boolLiteral, strLiteral), upStreamSchema, 1, 2);
    TransferableBlock result = op.nextBlock();
    // First block has two rows
    Assert.assertFalse(result.isErrorBlock());
    List<Object[]> resultRows = result.getContainer();
    List<Object[]> expectedRows = Arrays.asList(new Object[] { true, "str" }, new Object[] { true, "str" });
    Assert.assertEquals(resultRows.size(), expectedRows.size());
    Assert.assertEquals(resultRows.get(0), expectedRows.get(0));
    Assert.assertEquals(resultRows.get(1), expectedRows.get(1));
    // Second row is NoOp
    result = op.nextBlock();
    Assert.assertTrue(result.isNoOpBlock());
    // Third block has one row.
    result = op.nextBlock();
    Assert.assertFalse(result.isErrorBlock());
    resultRows = result.getContainer();
    expectedRows = Arrays.asList(new Object[] { true, "str" }, new Object[] { true, "str" }, new Object[] { true, "str" });
    Assert.assertEquals(resultRows.size(), expectedRows.size());
    Assert.assertEquals(resultRows.get(0), expectedRows.get(0));
    Assert.assertEquals(resultRows.get(1), expectedRows.get(1));
    Assert.assertEquals(resultRows.get(2), expectedRows.get(2));
}

