        assertEquals(sfd.getColumnsWithIndex(ColumnIndexType.INVERTED_INDEX), new HashSet<>(Collections.singletonList("col4")));
        assertEquals(sfd.getColumnsWithIndex(ColumnIndexType.H3_INDEX), new HashSet<>(Collections.singletonList("col5")));
        assertEquals(sfd.getColumnsWithIndex(ColumnIndexType.TEXT_INDEX), new HashSet<>(Arrays.asList("foo", "bar")));
