    indexMap.put(new StarTreeIndexMapUtils.IndexKey(StarTreeIndexMapUtils.IndexType.STAR_TREE, null), new StarTreeIndexMapUtils.IndexValue(0, 1));
    indexMap.put(new StarTreeIndexMapUtils.IndexKey(StarTreeIndexMapUtils.IndexType.FORWARD_INDEX, "dim0"), new StarTreeIndexMapUtils.IndexValue(1, 1));
    indexMap.put(new StarTreeIndexMapUtils.IndexKey(StarTreeIndexMapUtils.IndexType.FORWARD_INDEX, "dim1"), new StarTreeIndexMapUtils.IndexValue(2, 1));
    indexMap.put(new StarTreeIndexMapUtils.IndexKey(StarTreeIndexMapUtils.IndexType.FORWARD_INDEX, "count__*"), new StarTreeIndexMapUtils.IndexValue(3, 1));
    indexMaps.add(indexMap);
    indexMap = new HashMap<>();
    indexMap.put(new StarTreeIndexMapUtils.IndexKey(StarTreeIndexMapUtils.IndexType.STAR_TREE, null), new StarTreeIndexMapUtils.IndexValue(10, 3));
    indexMap.put(new StarTreeIndexMapUtils.IndexKey(StarTreeIndexMapUtils.IndexType.FORWARD_INDEX, "dimX"), new StarTreeIndexMapUtils.IndexValue(13, 3));
    indexMap.put(new StarTreeIndexMapUtils.IndexKey(StarTreeIndexMapUtils.IndexType.FORWARD_INDEX, "dimY"), new StarTreeIndexMapUtils.IndexValue(16, 3));
    indexMap.put(new StarTreeIndexMapUtils.IndexKey(StarTreeIndexMapUtils.IndexType.FORWARD_INDEX, "sum__dimX"), new StarTreeIndexMapUtils.IndexValue(19, 3));
    indexMaps.add(indexMap);
    File indexMapFile = new File(TEMP_DIR, StarTreeV2Constants.INDEX_MAP_FILE_NAME);
    StarTreeIndexMapUtils.storeToFile(indexMaps, indexMapFile);
    File indexFile = new File(TEMP_DIR, StarTreeV2Constants.INDEX_FILE_NAME);
    if (!indexFile.exists()) {
        indexFile.createNewFile();
    }
    byte[] data = new byte[32];
    for (int i = 0; i < data.length; i++) {
        data[i] = (byte) i;
    }
    try (PinotDataBuffer dataBuffer = PinotDataBuffer.mapFile(indexFile, false, 0, data.length, ByteOrder.LITTLE_ENDIAN, "StarTree V2 data buffer from: " + indexFile)) {
        dataBuffer.readFrom(0, data);
    }
    try (StarTreeIndexReader reader = new StarTreeIndexReader(TEMP_DIR, _segmentMetadata, ReadMode.mmap)) {
        // Check the bytes of the 1st ST index
        assertTrue(reader.hasIndexFor(0, "0", ColumnIndexType.INVERTED_INDEX));
        PinotDataBuffer buf = reader.getBuffer(0, "0", ColumnIndexType.INVERTED_INDEX);
        assertEquals(buf.size(), 1);
        assertEquals(buf.getByte(0), 0);
        assertTrue(reader.hasIndexFor(0, "dim0", ColumnIndexType.FORWARD_INDEX));
        buf = reader.getBuffer(0, "dim0", ColumnIndexType.FORWARD_INDEX);
        assertEquals(buf.size(), 1);
        assertEquals(buf.getByte(0), 1);
        assertTrue(reader.hasIndexFor(0, "dim1", ColumnIndexType.FORWARD_INDEX));
        buf = reader.getBuffer(0, "dim1", ColumnIndexType.FORWARD_INDEX);
        assertEquals(buf.size(), 1);
        assertEquals(buf.getByte(0), 2);
        assertTrue(reader.hasIndexFor(0, "count__*", ColumnIndexType.FORWARD_INDEX));
        buf = reader.getBuffer(0, "count__*", ColumnIndexType.FORWARD_INDEX);
        assertEquals(buf.size(), 1);
        assertEquals(buf.getByte(0), 3);
        // Check the bytes of the 2nd ST index
        assertTrue(reader.hasIndexFor(1, "1", ColumnIndexType.INVERTED_INDEX));
        buf = reader.getBuffer(1, "1", ColumnIndexType.INVERTED_INDEX);
        assertEquals(buf.size(), 3);
        assertEquals(buf.getByte(2), 12);
        assertTrue(reader.hasIndexFor(1, "dimX", ColumnIndexType.FORWARD_INDEX));
        buf = reader.getBuffer(1, "dimX", ColumnIndexType.FORWARD_INDEX);
        assertEquals(buf.size(), 3);
        assertEquals(buf.getByte(2), 15);
        assertTrue(reader.hasIndexFor(1, "dimY", ColumnIndexType.FORWARD_INDEX));
        buf = reader.getBuffer(1, "dimY", ColumnIndexType.FORWARD_INDEX);
        assertEquals(buf.size(), 3);
        assertEquals(buf.getByte(2), 18);
        assertTrue(reader.hasIndexFor(1, "sum__dimX", ColumnIndexType.FORWARD_INDEX));
        buf = reader.getBuffer(1, "sum__dimX", ColumnIndexType.FORWARD_INDEX);
        assertEquals(buf.size(), 3);
        assertEquals(buf.getByte(2), 21);
    }
